typedef enum {
    Z_OPENRESULT_TAG_OK,
    Z_OPENRESULT_TAG_ERR,
} z_t1381_tag_t;
struct z_t1381_t {
    z_t1381_tag_t tag;
    void* data;
};
static void z_t1381_destroy(z_t1381_t* u) {
    if (!u) return;
    if (!u->data) return;
    switch (u->tag) {
        case Z_OPENRESULT_TAG_OK:
            z_t75_free((z_t75_t*)u->data);
            free(u->data);
            break;
        case Z_OPENRESULT_TAG_ERR:
            z_t1382_destroy((z_t1382_t*)u->data);
            free(u->data);
            break;
        default: break;
    }
}

