            if (!inherit_in) dup2(null_fd, 0);
            if (!inherit_out) dup2(out_fd, 1);
            if (!inherit_err) dup2(err_fd, 2);
            if (null_fd >= 0) close(null_fd);
            if (out_fd >= 0) close(out_fd);
            if (err_fd >= 0) close(err_fd);
            execvp(c_argv[0], c_argv);
